import React from "react";
import {
  FaUserEdit,
  FaUserShield,
  FaCalendarAlt,
  FaIdCard,
  FaMapMarkerAlt,
  FaShieldAlt,
  FaPhone,
  FaImage,
  FaUsers,
  FaGraduationCap,
  FaBook,
  FaChevronLeft,
  FaChevronDown,
  FaCommentDots,
} from "react-icons/fa";
import InfoField from "./InfoFieldComponenet";
import Loader from "./LoaderComponent";
import withRouter from "./withRouter";


const API_URL = "https://iranaserviceapp.ir/test/api";

class PersonalInfoPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      person: null,
      loading: true,
      error: false,
    };

    this.handleBack = this.handleBack.bind(this);
    this.handleChat = this.handleChat.bind(this);
  }

  componentDidMount() {
    this.getProfile();
  }

  // =========================================================
  // دریافت پروفایل
  // =========================================================

  getProfile = () => {
    const token = localStorage.getItem("token");
    const { id } = this.props.params;

    this.setState({
      loading: true,
      error: false,
    });

    fetch(`${API_URL}/profile?id=${id}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت پروفایل");
        }

        return response.json();
      })
      .then((data) => {
        console.log("PROFILE API:", data);

        if (!data.user) {
          throw new Error("اطلاعات کاربر دریافت نشد");
        }

        this.setState({
          person: data.user,
          loading: false,
        });
      })
      .catch((error) => {
        console.error(
          "GET PROFILE ERROR:",
          error
        );

        this.setState({
          person: null,
          loading: false,
          error: true,
        });
      });
  };

  // =========================================================
  // ساخت آدرس تصویر
  // =========================================================

  getImageUrl = (image) => {
    if (!image) {
      return "";
    }

    return `${API_URL}/files/user${image}`;
  };

  // =========================================================
  // وضعیت نظام وظیفه
  // =========================================================

  getMilitaryStatus = (value) => {
    if (String(value) === "1") {
      return "پایان خدمت";
    }

    if (String(value) === "2") {
      return "معاف";
    }

    if (String(value) === "3") {
      return "در حال خدمت";
    }

    if (String(value) === "0") {
      return "مشمول";
    }

    return value || "---";
  };

  // =========================================================
  // وضعیت تأهل
  // =========================================================

  getMarriedStatus = (value) => {
    if (String(value) === "1") {
      return "متاهل";
    }

    if (String(value) === "0") {
      return "مجرد";
    }

    return value || "---";
  };

  // =========================================================
  // تخصص‌ها
  // =========================================================

  getSpecialties = (specials) => {
    if (!specials) {
      return "---";
    }

    try {
      let list = specials;

      if (typeof specials === "string") {
        list = JSON.parse(specials);
      }

      if (!Array.isArray(list)) {
        return "---";
      }

      if (list.length === 0) {
        return "---";
      }

      return list
        .map((item) => {
          if (typeof item === "string") {
            return item;
          }

          if (item.name) {
            return item.name;
          }

          return "";
        })
        .filter(Boolean)
        .join("، ");
    } catch (error) {
      console.error(
        "SPECIALTIES ERROR:",
        error
      );

      return "---";
    }
  };

  // =========================================================
  // بازگشت
  // =========================================================

  handleBack() {
    if (this.props.history) {
      this.props.history.goBack();
      return;
    }

    console.log("بازگشت به صفحه قبل");
  }

  // =========================================================
  // گفتگو
  // =========================================================

  handleChat() {
    console.log("رفتن به گفتگو");
  }

  // =========================================================
  // Render
  // =========================================================

  render() {
    const {
      person,
      loading,
      error,
    } = this.state;

    if (loading) {
      return <Loader />;
    }

    if (error || !person) {
      return (
        <div
          className="container px-3 pt-4"
          dir="rtl"
        >
          <div className="alert alert-danger text-center">
            خطا در دریافت اطلاعات پروفایل
          </div>
        </div>
      );
    }

    const nationalCardImage =
      this.getImageUrl(
        person.national_image
      );

    const selfieImage =
      this.getImageUrl(person.image);

    const specialties =
      this.getSpecialties(
        person.specials
      );

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">
          {/* هدر */}

          <div className="d-flex align-items-center justify-content-between mb-3">
            <button
              type="button"
              onClick={this.handleBack}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaChevronLeft size={14} />
            </button>

            <h1 className="fs-6 fw-semibold text-dark m-0">
              اطلاعات شخصی
            </h1>

            <span></span>
          </div>

          {/* اطلاعات شخصی */}

          <InfoField
            icon={<FaUserEdit size={18} />}
            label="نام"
            value={person.name || "---"}
          />

          <InfoField
            icon={<FaUserShield size={18} />}
            label="نام خانوادگی"
            value={person.family || "---"}
          />

          <InfoField
            icon={<FaCalendarAlt size={18} />}
            label="تاریخ تولد"
            value={person.birthdate || "---"}
          />

          <InfoField
            icon={<FaIdCard size={18} />}
            label="کد ملی"
            value={
              person.national_code || "---"
            }
          />

          <InfoField
            icon={<FaMapMarkerAlt size={18} />}
            label="محل تولد"
            value={
              person.birth_city || "---"
            }
          />

          {/* تصویر کارت ملی */}

          <div className="d-flex align-items-start justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">
            <span className="text-muted">
              تصویر کارت ملی:
            </span>

            {nationalCardImage ? (
              <img
                src={''+nationalCardImage}
                alt="تصویر کارت ملی"
                className="rounded-3 border"
                style={{
                  width: 160,
                  height: 110,
                  objectFit: "cover",
                }}
              />
            ) : (
              <span className="text-muted">
                ثبت نشده
              </span>
            )}
          </div>

          <InfoField
            icon={<FaShieldAlt size={18} />}
            label="وضعیت نظام وظیفه"
            value={this.getMilitaryStatus(
              person.sarbazi
            )}
          />

          <InfoField
            icon={<FaPhone size={18} />}
            label="شماره تماس"
            value={person.mobile || "---"}
          />

          <InfoField
            icon={<FaMapMarkerAlt size={18} />}
            label="آدرس"
            value={person.address || "---"}
          />

          <InfoField
            icon={<FaUsers size={18} />}
            label="وضعیت تاهل"
            value={this.getMarriedStatus(
              person.married
            )}
          />

          {/* سوابق تحصیلی */}

          <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
            سوابق تحصیلی:
          </h2>

          <InfoField
            icon={
              <FaGraduationCap size={18} />
            }
            label="مدرک تحصیلی"
            value={person.degree || "---"}
          />

          <InfoField
            icon={<FaBook size={18} />}
            label="رشته تحصیلی"
            value={person.reshte || "---"}
          />

          {/* تصویر سلفی */}

          <div className="d-flex align-items-start justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">
            <span className="text-muted">
              تصویر سلفی:
            </span>

            {selfieImage ? (
              <img
                src={selfieImage}
                alt="تصویر سلفی"
                className="rounded-3 border"
                style={{
                  width: 160,
                  height: 140,
                  objectFit: "cover",
                }}
              />
            ) : (
              <span className="text-muted">
                ثبت نشده
              </span>
            )}
          </div>

          {/* تخصص‌ها */}

          <InfoField
            icon={
              <FaChevronDown
                className="text-secondary"
                size={12}
              />
            }
            label="تخصص‌ها"
            value={specialties}
          />

          {/* استان مورد نظر */}

          <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
            استان مورد نظر:
          </h2>

          <InfoField
            icon={
              <FaMapMarkerAlt size={18} />
            }
            label="استان"
            value={
              person.state_model?.name ||
              "---"
            }
          />

          <InfoField
            icon={<FaMapMarkerAlt size={18} />}
            label="شهر"
            value={
              person.city_model?.name ||
              "---"
            }
          />
        </div>
      </div>
    );
  }
}

export default withRouter(PersonalInfoPage);
